if(!function_exists('mvm_newsradar_schedule_ai_retry_v3')){function mvm_newsradar_schedule_ai_retry_v3($cycle,$delay=60){$cycle=(string)$cycle;if($cycle==='')return;$args=[$cycle];if(!wp_next_scheduled('mvm_bh_news_radar_ai_batch',$args))wp_schedule_single_event(time()+max(5,(int)$delay),'mvm_bh_news_radar_ai_batch',$args);}}
