 $rows=get_option('mvm_bh_news_radar_results',[]);if(!is_array($rows))return;$excluded=[];$sources=get_option('mvm_bh_sources',[]);foreach(is_array($sources)?$sources:[] as $s)if(is_array($s)&&!empty($s['excluded'])&&!empty($s['id']))$excluded[(int)$s['id']]=true;$changed=false;
 foreach($rows as &$r){if(!is_array($r)||empty($r['ai_pending']))continue;$sid=(int)($r['source_id']??0);if($sid&&isset($excluded[$sid])){$r['ai_pending']=0;$r['email_pending']=0;$r['status']='controleren';$r['reason']='Bron is uitgesloten van de Nieuwsradar; deze kandidaat is niet naar AI gestuurd.';$changed=true;continue;}if(class_exists('MvM_Hub4_Newsradar_Local_Scope')){$scope=MvM_Hub4_Newsradar_Local_Scope::assess($r);$r['mvm_scope_score']=(int)($scope['score']??0);$r['mvm_scope_decision']=(string)($scope['decision']??'review');if(($scope['decision']??'')==='reject'){$r['ai_pending']=0;$r['email_pending']=0;$r['status']='niet_mierlo';$r['reason']='Mierlo-scopefilter: '.implode(' ',(array)($scope['reasons']??[]));$changed=true;}}}unset($r);if($changed)update_option('mvm_bh_news_radar_results',$rows,false);
 $pending=[];foreach($rows as $r){if(!is_array($r)||empty($r['ai_pending'])||!empty($r['dismissed']))continue;$pending[]=$r;if(count($pending)>=2)break;}if(!$pending)return;
