 $processed=mvm_newsradar_apply_gemini_v1($analysis);if($processed<1){update_option('mvm_newsradar_gemini_fallback_status_v1',['ok'=>false,'time'=>wp_date(DATE_ATOM),'message'=>'Gemini gaf geen toepasbare Radar-beoordeling terug.','batch'=>2,'retry_seconds'=>60],false);mvm_newsradar_schedule_ai_retry_v3($cycle,60);return;}
 $model=(string)get_option('mvm_newsradar_gemini_last_model_v1','gemini-3.7-flash');$rows_after=get_option('mvm_bh_news_radar_results',[]);$remaining=0;foreach(is_array($rows_after)?$rows_after:[] as $r)if(is_array($r)&&!empty($r['ai_pending'])&&empty($r['dismissed']))$remaining++;$state=get_option('mvm_bh_news_radar_state',[]);if(is_array($state)&&($cycle===''||(string)($state['cycle']??'')===(string)$cycle)){$state['running']=$remaining?1:0;$state['phase']=$remaining?'ai':'done';$state['ai_processed']=(int)($state['ai_processed']??0)+$processed;$state['last_message']=$processed.' kandidaten door '.$model.' beoordeeld (automatische providerfallback, batch 2; 20s cadans).'.($remaining?' '.$remaining.' wachten nog op AI.':' AI-wachtrij leeg; cyclus afgerond.');update_option('mvm_bh_news_radar_state',$state,false);}update_option('mvm_newsradar_gemini_fallback_status_v1',['ok'=>true,'time'=>wp_date(DATE_ATOM),'processed'=>$processed,'remaining'=>$remaining,'model'=>$model,'batch'=>2,'cadence_seconds'=>20],false);if($remaining)mvm_newsradar_schedule_ai_retry_v3($cycle,20);
