add_action('init',static function(){remove_action('mvm_bh_news_radar_ai_batch','mvm_newsradar_google_fallback_hook_v1',5);remove_action('mvm_bh_news_radar_ai_batch','mvm_newsradar_google_fallback_hook_v2',5);remove_action('mvm_bh_news_radar_ai_batch','mvm_newsradar_google_fallback_hook_v3',5);remove_action('mvm_bh_news_radar_ai_batch','mvm_newsradar_google_fallback_hook_v4',5);add_action('mvm_bh_news_radar_ai_batch','mvm_newsradar_google_fallback_hook_v5',5,1);$state=get_option('mvm_bh_news_radar_state',[]);if(!is_array($state)||empty($state['cycle']))return;$should_resume=!empty($state['running'])&&(string)($state['phase']??'')==='ai';if(!$should_resume&&function_exists('mvm_newsradar_should_google_fallback_v1')&&mvm_newsradar_should_google_fallback_v1()){$rows=get_option('mvm_bh_news_radar_results',[]);foreach(is_array($rows)?$rows:[] as $r){if(is_array($r)&&!empty($r['ai_pending'])&&empty($r['dismissed'])){$should_resume=true;break;}}if($should_resume){$state['running']=1;$state['phase']='ai';$state['last_message']='Automatische AI-fallback hervat de vastgelopen Nieuwsradar-cyclus.';update_option('mvm_bh_news_radar_state',$state,false);}}if($should_resume)mvm_newsradar_schedule_ai_retry_v3((string)$state['cycle'],5);},20);